local shothook;
shothook = hookmetamethod(game, "__namecall", function(self, ...) 
    local args = {...}
    local method = getnamecallmethod()

    if tostring(self) == "Swing" and method == "FireServer" then
return nil
end
return shothook(self, unpack(args))
end)

