local FunTab = Window:CreateTab("Fun Client sided tab (sometimes FE)", nil) -- Title, Image

local Button4 = FunTab:CreateButton({
   Name = "Back flip R15",
   Callback = function()
        local animator = game.Players.LocalPlayer.Character.Humanoid.Animator
        local backflip = Instance.new("Animation")
        backflip.AnimationId = "rbxassetid://91583499354581"

        -- Load the animation onto the Animator
        local backflipTrack = animator:LoadAnimation(backflip)

        -- Play the animation
        backflipTrack:Play()

        -- (Optional) Wait for the animation to finish before doing something else
        backflipTrack.Completed:Wait(1)
        local sui = Instance.new("Sound")
        sui.SoundId = "rbxassetid://7681560017"
        sui.Parent = game.Workspace
        sui:Play()
   end,
})

